import React, { PropsWithChildren, ReactNode } from 'react';
import { isElement } from 'react-is';

import { uuidv4 } from '../../../core/utils/uuidv4.js';
import { iterateChartInteractionsSlots } from '../../core/functions/iterate-chart-interactions-slots.js';
import { ChartInteractions } from '../../core/slots/chart-interactions/ChartInteractions.js';
import { ChartToolbar } from '../../core/slots/toolbar/ChartToolbar.js';
import { DownloadData } from '../../core/slots/toolbar/DownloadData.js';
import { WithId } from '../../core/types/with-id.js';
import { Annotations } from '../slots/annotations/Annotations.js';
import { Marker } from '../slots/annotations/Marker.js';
import { Track } from '../slots/annotations/Track.js';
import { Legend } from '../slots/Legend.js';
import { HistogramThresholdProps, Threshold } from '../slots/Threshold.js';
import { Tooltip } from '../slots/Tooltip.js';
import { XAxis } from '../slots/XAxis.js';
import { YAxis } from '../slots/YAxis.js';
import {
  HistogramAnnotationsTrackRendererProps,
  HistogramAnnotationsMarkerProps,
  HistogramAnnotationsConfigProps,
} from '../types/histogram-annotations.js';
import {
  HistogramChartYAxisProps,
  HistogramChartXAxisProps,
  HistogramChartTooltipProps,
  HistogramChartToolbarConfig,
  HistogramChartSlots,
  HistogramChartLegendProps,
  HistogramChartToolbarProps,
} from '../types/histogram.js';

export const iterateSlots = (
  children: React.ReactNode,
): HistogramChartSlots => {
  let slots: HistogramChartSlots = {
    legend: {},
    xAxis: {},
    yAxis: [],
    tooltip: {},
    toolbar: {},
    interactions: {},
    thresholds: [],
  };

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      switch (child.type) {
        case ChartInteractions: {
          const { children, ...previousInteractions } = child.props;

          const interactions = iterateChartInteractionsSlots(children);

          slots = {
            ...slots,
            interactions: {
              ...previousInteractions,
              ...interactions,
            },
          };
          break;
        }
        case XAxis: {
          const xAxis = child.props as HistogramChartXAxisProps;
          slots = {
            ...slots,
            xAxis,
          };
          break;
        }
        case YAxis: {
          const yAxis = child.props as HistogramChartYAxisProps;

          slots.yAxis.push(yAxis);
          break;
        }
        case Legend: {
          const legend = child.props as HistogramChartLegendProps;

          slots = {
            ...slots,
            legend,
          };
          break;
        }
        case Tooltip: {
          const tooltip = child.props as HistogramChartTooltipProps;
          slots = {
            ...slots,
            tooltip,
          };
          break;
        }
        case ChartToolbar: {
          const { children, ...toolbar } =
            child.props as PropsWithChildren<HistogramChartToolbarProps>;
          const childrenToolbar = iterateChartToolbarSlots(children);

          slots = {
            ...slots,
            toolbar: {
              enabled: true,
              ...toolbar,
              ...childrenToolbar,
            },
          };
          break;
        }
        case Annotations: {
          const { children, ...annotationsProps } =
            child.props as React.PropsWithChildren<HistogramAnnotationsConfigProps>;

          const tracks = iterateTrackSlots(children);

          const annotations = {
            ...annotationsProps,
            tracks,
          };

          slots = {
            ...slots,
            annotations,
          };
          break;
        }
        case Threshold: {
          const thresholdProps = child.props as HistogramThresholdProps;

          slots.thresholds.push(thresholdProps);

          break;
        }
      }
    }
  });

  return slots;
};

/**
 * Generate chart config based on slots
 * @param children - CharInteraction children
 * @returns ChartInteraction slot config
 */
const iterateChartToolbarSlots = (
  children: ReactNode,
): HistogramChartToolbarConfig => {
  let toolbar = {};

  React.Children.forEach(children, (childToolbar) => {
    if (isElement(childToolbar) && childToolbar.type === DownloadData) {
      toolbar = {
        ...toolbar,
        downloadData: { enabled: true },
      };
    }
  });

  return toolbar;
};

/**
 * Generate config based on the Tracks and Markers slots
 * @param children - Annotations children
 * @returns tracks configuration including the markers
 */
const iterateTrackSlots = (children: ReactNode) => {
  const tracks: HistogramAnnotationsTrackRendererProps[] = [];

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      if (child.type === Track) {
        const { children, ...trackProps } = child.props;
        const currentTrack: {
          markers: WithId<HistogramAnnotationsMarkerProps>[];
        } = {
          ...trackProps,
          markers: [],
        };

        React.Children.forEach(children, (child) => {
          if (isElement(child)) {
            if (child.type === Marker) {
              const markerProps = { ...child.props, id: uuidv4() };
              currentTrack.markers.push(markerProps);
            }
          }
        });
        tracks.push(currentTrack);
      }
    }
  });

  return tracks;
};
